from proto import *
def spir(a0, a1, r0, r1, step=3): return arcpts(lambda a: r0 + (r1-r0)*(a-a0)/(a1-a0), a0, a1, step)
def H(tail=(0,-44,35,35), tip=[(24.5,-24),(21.5,-27),(18,-26.5)], headE=[(12.3,-27.2),(8,-34),(3,-43),(-1,-52),(-5,-61),(-9,-69)],
      headW=[(-30,-69),(-35,-66),(-39,-59),(-42,-50),(-42.5,-41),(-40,-33)], rimhead=[], sl=(-148,-174,28,28), north=[], endR=35):
    return spir(*tail) + tip + headE + headW + rimhead + spir(sl[0], sl[1], sl[2], sl[3]) + north + [P(endR,-179.9)]
evaluate(H(), 'z8')
evaluate(H(headW=[(-30,-69),(-35,-66),(-39,-59),(-41,-50),(-41,-41),(-38,-33)], rimhead=[P(42,-142)], sl=(-148,-172,27,27), north=[P(36,-177)], endR=36), 'z9')
evaluate(H(tail=(0,-40,35,34), tip=[(23.5,-22),(21.5,-27),(18,-26.5)], headW=[(-30,-69),(-35,-66),(-39,-59),(-41,-50),(-41,-41),(-38,-33)], rimhead=[P(42,-142)], sl=(-148,-172,27,27), north=[P(36,-177)], endR=35), 'z10')
